CREATE COLUMN TABLE "TEST_AP"."OTRB" ("AbsEntry" INTEGER CS_INT NOT NULL , "BPLId" INTEGER CS_INT, "GPCId" INTEGER CS_INT, "GPCCode" NVARCHAR(6), "Year" SMALLINT CS_INT, "PrdType" NVARCHAR(1), "PrdNum" INTEGER CS_INT, "PrdDate" LONGDATE CS_LONGDATE, "RunName" NVARCHAR(100) NOT NULL , "RunDate" LONGDATE CS_LONGDATE, "Status" NVARCHAR(1), "StateTax" NVARCHAR(1) DEFAULT 'N', "DueDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTRB_SECONDARY" ON "TEST_AP"."OTRB" ( "RunName" ASC )